CREATE TABLE work_orders(id CHAR(36) PRIMARY KEY,room_id CHAR(36) NOT NULL,title VARCHAR(200) NOT NULL,description VARCHAR(2000) NOT NULL,reporter_id CHAR(36) NOT NULL,reporter_email VARCHAR(200) NOT NULL,repairer_id CHAR(36),state VARCHAR(30) NOT NULL,source_version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE commands(actor_id CHAR(36) NOT NULL,idempotency_key VARCHAR(100) NOT NULL,fingerprint CHAR(64) NOT NULL,order_id CHAR(36) NOT NULL,PRIMARY KEY(actor_id,idempotency_key));
CREATE TABLE sync_tasks(id CHAR(36) PRIMARY KEY,order_id CHAR(36) NOT NULL,room_id CHAR(36) NOT NULL,source_version BIGINT NOT NULL,desired_state VARCHAR(20) NOT NULL,request_id VARCHAR(64) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',attempts INT NOT NULL DEFAULT 0,next_attempt TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),last_error VARCHAR(500),created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(order_id) REFERENCES work_orders(id));
CREATE INDEX ix_tasks_pending ON sync_tasks(status,next_attempt);
CREATE TABLE notifications(id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,email VARCHAR(200) NOT NULL,message VARCHAR(500) NOT NULL,is_read BOOLEAN NOT NULL DEFAULT FALSE,mail_state VARCHAR(20) NOT NULL DEFAULT 'PENDING',mail_attempts INT NOT NULL DEFAULT 0,next_attempt TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE audit_events(id CHAR(36) PRIMARY KEY,actor_id VARCHAR(50) NOT NULL,action VARCHAR(80) NOT NULL,request_id VARCHAR(64) NOT NULL,order_id CHAR(36) NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
